def rule_early_narrative_principal_offices_sentence(doc: dict) -> list[dict]:
    """Match early narrative sentences that explicitly state the headquarters or principal offices location."""
    try:
        results = []
        for span in doc.get("texts", []):
            if span.get("page_no", 999) > 15:
                continue
            if span.get("label") != "text":
                continue

            text = " ".join((span.get("text") or "").split())
            lowered = text.lower()
            if (
                "principal executive offices are located at" in lowered
                or "our principal executive offices are located at" in lowered
                or "headquartered in" in lowered
            ):
                results.append(span)

        return results
    except Exception:
        return []

def rule_page12_address_before_zip_label(doc: dict) -> list[dict]:
    """Match the early-page address span immediately before a standalone zip-code label."""
    try:
        import re

        street_re = re.compile(
            r"\b(?:street|st\.?|drive|dr\.?|avenue|ave\.?|road|rd\.?|way|plaza|"
            r"boulevard|blvd\.?|lane|ln\.?|suite|ste\.?|park|tower)\b",
            re.I,
        )

        results = []
        texts = doc.get("texts", [])
        valid_labels = {
            "(zip code)",
            "zip code",
            "(address of principal executive offices) (zip code)",
            "(address of principal executive offices and zip code)",
        }

        for i, span in enumerate(texts):
            if span.get("page_no", 999) > 2:
                continue

            label_text = " ".join((span.get("text") or "").split())
            if label_text.lower() not in valid_labels:
                continue
            if i - 1 < 0:
                continue

            prev = texts[i - 1]
            if prev.get("page_no") != span.get("page_no"):
                continue

            prev_text = " ".join((prev.get("text") or "").split())
            prev_lowered = prev_text.lower()
            if any(
                marker in prev_lowered
                for marker in (
                    "employer identification",
                    "i.r.s.",
                    "irs employer",
                    "commission file",
                    "telephone number",
                    "former name",
                )
            ):
                continue
            if not (
                street_re.search(prev_text)
                or "," in prev_text
                or re.fullmatch(r"[A-Z]{2}", prev_text.strip())
            ):
                continue

            results.append(prev)

        return results
    except Exception:
        return []

def rule_page12_inline_address_label_span(doc: dict) -> list[dict]:
    """Match early-page spans that contain both the address text and the principal-offices label."""
    try:
        import re

        street_re = re.compile(
            r"\b(?:street|st\.?|drive|dr\.?|avenue|ave\.?|road|rd\.?|way|plaza|"
            r"boulevard|blvd\.?|lane|ln\.?|suite|ste\.?|park|tower)\b",
            re.I,
        )

        results = []
        for span in doc.get("texts", []):
            if span.get("page_no", 999) > 2:
                continue

            text = " ".join((span.get("text") or "").split())
            lowered = text.lower()
            if "address of principal executive offices" not in lowered:
                continue

            before_label = lowered.split("address of principal executive offices", 1)[0]
            if street_re.search(text) or "," in text or re.search(r"\d", before_label):
                results.append(span)

        return results
    except Exception:
        return []

